        try {
            const data = localStorage.getItem(this.storageKey);
            if (data) {
                this.root = JSON.parse(data);
            } else {
                this.save();
            }
        } catch (e) {
            console.error('Failed to load FS:', e);
            this.root = { type: 'dir', children: { 'documents': { type: 'dir', children: {} }, 'notes.txt': { type: 'file', content: 'Welcome to WebOS!' } } };
            this.save();
        }
    }

    save() { localStorage.setItem(this.storageKey, JSON.stringify(this.root)); }

    init() { console.log('FS initialized'); }

    mkdir(name) {
        if (name && !this.root.children[name]) {
            this.root.children[name] = { type: 'dir', children: {} };
            this.save();
            return true;
        }
        return false;
    }

    createFile(name) {
        if (name && !this.root.children[name]) {
            this.root.children[name] = { type: 'file', content: '' };
            this.save();
            return true;
        }
        return false;
    }

    writeFile(path, content) {
        const parts = path.split('/');
        let current = this.root;
        for (let i = 0; i < parts.length - 1; i++) {
            if (current.children[parts[i]] && current.children[parts[i]].type === 'dir') {
                current = current.children[parts[i]];
            } else {
                return false;
            }
        }
        const fileName = parts[parts.length - 1];
        if (current.children[fileName]) {
            current.children[fileName].content = content;
            this.save();
            return true;
        }
        return false;
    }
}

