/**
 * Notepad App
 */
export class NotepadApp {
    constructor(kernel) {
        this.kernel = kernel;
    }
    render(container, params) {
        container.innerHTML = '<div class="notepad-container"><div class="notepad-toolbar"><button id="note-new">New</button><button id="note-save">Save</button></div><textarea id="note-editor"></textarea></div>';
        const editor = document.getElementById('note-editor');
        if (params && params.filename) {
            const f = this.kernel.fs.root.children[params.filename];
            if (f) editor.value = f.content;
        }
        document.getElementById('note-new').onclick = () => editor.value = '';
        document.getElementById('note-save').onclick = () => {
            const name = prompt("Save as (filename):") || 'note.txt';
            this.kernel.fs.createFile(name);
            this.kernel.fs.writeFile(name, editor.value);
            alert('Saved!');
        };
    }
}

